import{_ as t,a0 as o,w as c,s as r,ao as p,I as e,x as s,a1 as l,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const A=JSON.parse('{"title":"Google Analytics 的一些用法介绍 | LCTT x X-CMD","titleTemplate":false,"description":"Google Analytics 的一些用法介绍 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Google Analytics 的一些用法介绍 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Google Analytics 的一些用法介绍 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20191004 All That You Can Do with Google Analytics, and More","title":"Google Analytics 的一些用法介绍","tag":"201910","desc":""},"relativePath":"201910/20191004 All That You Can Do with Google Analytics, and More.md","filePath":"[post].md"}'),d={name:"201910/20191004 All That You Can Do with Google Analytics, and More.md"};function g(h,a,u,k,b,y){const n=o("Link");return c(),r("div",null,[a[21]||(a[21]=p('<h1 id="google-analytics-的一些用法介绍" tabindex="-1">Google Analytics 的一些用法介绍 <a class="header-anchor" href="#google-analytics-的一些用法介绍" aria-label="Permalink to “Google Analytics 的一些用法介绍”">​</a></h1><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/10/Analytics-illustration.jpg?resize=696%2C396&amp;ssl=1" alt="" title="Analytics illustration"></p><p>Google Analytics （GA）这个最流行的用户活动追踪工具我们或多或少都听说过甚至使用过，但它的用途并不仅仅限于对页面访问的追踪。作为一个既实用又流行的工具，它已经受到了广泛的欢迎，因此我们将要在下文中介绍如何在各种 Angular 和 React 单页应用中使用 Google Analytics。</p><p>这篇文章源自这样一个问题：如何对单页应用中的页面访问进行跟踪？</p><p>通常来说，有很多的方法可以解决这个问题，在这里我们只讨论其中的一种方法。下面我会使用 Angular 来写出对应的实现，如果你使用的是 React，相关的用法和概念也不会有太大的差别。接下来就开始吧。</p><h3 id="准备好应用程序" tabindex="-1">准备好应用程序 <a class="header-anchor" href="#准备好应用程序" aria-label="Permalink to “准备好应用程序”">​</a></h3><p>首先需要有一个<ruby>追踪 ID<rt>tracking ID</rt></ruby>。在开始编写业务代码之前，要先准备好一个追踪 ID，通过这个唯一的标识，Google Analytics 才能识别出某个点击或者某个页面访问是来自于哪一个应用。</p><p>按照以下的步骤：</p>',8)),e("ol",null,[e("li",null,[a[1]||(a[1]=s("访问 ",-1)),l(n,{href:"https://analytics.google.com"},{default:i(()=>[...a[0]||(a[0]=[s("https://analytics.google.com",-1)])]),_:1}),a[2]||(a[2]=s("；",-1))]),a[3]||(a[3]=e("li",null,"提交指定信息以完成注册，并确保可用于 Web 应用，因为我们要开发的正是一个 Web 应用；",-1)),a[4]||(a[4]=e("li",null,"同意相关的条款，生成一个追踪 ID；",-1)),a[5]||(a[5]=e("li",null,"保存好追踪 ID。",-1))]),a[22]||(a[22]=p(`<p>追踪 ID 拿到了，就可以开始编写业务代码了。</p><h3 id="添加-analytics-js-脚本" tabindex="-1">添加 analytics.js 脚本 <a class="header-anchor" href="#添加-analytics-js-脚本" aria-label="Permalink to “添加 analytics.js 脚本”">​</a></h3><p>Google 已经帮我们做好了接入之前需要做的所有事情，接下来就是我们的工作了。不过我们要做的也很简单，只需要把下面这段脚本添加到应用的 <code>index.html</code> 里，就可以了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;script&gt;</span></span>
<span class="line"><span>(function(i,s,o,g,r,a,m){i[&#39;GoogleAnalyticsObject&#39;]=r;i[r]=i[r]||function(){</span></span>
<span class="line"><span>(i[r].q=i[r].q||[]).push(arguments)},i[r].l=1*new Date();a=s.createElement(o),</span></span>
<span class="line"><span>m=s.getElementsByTagName(o)[0];a.async=1;a.src=g;m.parentNode.insertBefore(a,m)</span></span>
<span class="line"><span>})(window,document,&#39;script&#39;,&#39;https://www.google-analytics.com/analytics.js&#39;,&#39;ga&#39;);</span></span>
<span class="line"><span>&lt;/script&gt;</span></span></code></pre></div><p>现在我们来看一下 Google Analytics 是如何在应用程序中初始化的。</p><h3 id="创建追踪器" tabindex="-1">创建追踪器 <a class="header-anchor" href="#创建追踪器" aria-label="Permalink to “创建追踪器”">​</a></h3><p>首先创建一个应用程序的追踪器。在 <code>app.component.ts</code> 中执行以下两个步骤：</p><ol><li>声明一个名为 <code>ga</code>，类型为 <code>any</code> 的全局变量（在 Typescript 中需要制定变量类型）；</li><li>将下面一行代码加入到 <code>ngInInit()</code> 中。</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ga(&#39;create&#39;, &lt;你的追踪 ID&gt;, &#39;auto&#39;);</span></span></code></pre></div><p>这样就已经成功地在应用程序中初始化了一个 Google Analytics 的追踪器了。由于追踪器的初始化是在 <code>OnInit()</code> 函数中执行的，因此每当应用程序启动，追踪器就会启动。</p><h3 id="在单页应用中记录页面访问情况" tabindex="-1">在单页应用中记录页面访问情况 <a class="header-anchor" href="#在单页应用中记录页面访问情况" aria-label="Permalink to “在单页应用中记录页面访问情况”">​</a></h3><p>我们需要实现的是记录<ruby>访问路由<rt>route-visits</rt></ruby>。</p><p>如何记录用户在一个应用中不同部分的访问，这是一个难点。从功能上来看，单页应用中的路由对应了传统多页面应用中各个页面之间的跳转，因此我们需要记录访问路由。要做到这一点尽管不算简单，但仍然是可以实现的。在 <code>app.component.ts</code> 的 <code>ngOnInit()</code> 函数中添加以下的代码片段：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import { Router, NavigationEnd } from &#39;@angular/router&#39;;</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>constructor(public router: Router) {}</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>this.router.events.subscribe(</span></span>
<span class="line"><span>    event =&gt; {</span></span>
<span class="line"><span>        if (event instanceof NavigationEnd) {</span></span>
<span class="line"><span>            ga(&#39;set&#39;, &#39;page&#39;, event.urlAfterRedirects);</span></span>
<span class="line"><span>            ga(&#39;send&#39;, { hitType: &#39;pageview&#39;, hitCallback: () =&gt; { this.pageViewSent = true; }});</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    } </span></span>
<span class="line"><span>);</span></span></code></pre></div><p>神奇的是，只需要这么几行代码，就实现了 Angular 应用中记录页面访问情况的功能。</p><p>这段代码实际上做了以下几件事情：</p><ol><li>从 Angular Router 中导入了 <code>Router</code>、<code>NavigationEnd</code>；</li><li>通过构造函数中将 <code>Router</code> 添加到组件中；</li><li>然后订阅 <code>router</code> 事件，也就是由 Angular Router 发出的所有事件；</li><li>只要产生了一个 <code>NavigationEnd</code> 事件实例，就将路由和目标作为一个页面访问进行记录。</li></ol><p>这样，只要使用到了页面路由，就会向 Google Analytics 发送一条页面访问记录，在 Google Analytics 的在线控制台中可以看到这些记录。</p><p>类似地，我们可以用相同的方式来记录除了页面访问之外的活动，例如某个界面的查看次数或者时长等等。只要像上面的代码那样使用 <code>hitCallBack()</code> 就可以在有需要收集的数据的时候让应用程序作出反应，这里我们做的事情仅仅是把一个变量的值设为 <code>true</code>，但实际上 <code>hitCallBack()</code> 中可以执行任何代码。</p><h3 id="追踪用户交互活动" tabindex="-1">追踪用户交互活动 <a class="header-anchor" href="#追踪用户交互活动" aria-label="Permalink to “追踪用户交互活动”">​</a></h3><p>除了页面访问记录之外，Google Analytics 还经常被用于追踪用户的交互活动，例如某个按钮的点击情况。“提交按钮被用户点击了多少次？”，“产品手册会被经常查阅吗？”这些都是 Web 应用程序的产品评审会议上的常见问题。这一节我们将会介绍如何实现这些数据的统计。</p><h4 id="按钮点击" tabindex="-1">按钮点击 <a class="header-anchor" href="#按钮点击" aria-label="Permalink to “按钮点击”">​</a></h4><p>设想这样一种场景，需要统计到应用程序中某个按钮或链接被点击的次数，这是一个和注册之类的关键动作关系最密切的数据指标。下面我们来举一个例子：</p><p>假设应用程序中有一个“感兴趣”按钮，用于显示即将推出的活动，你希望通过统计这个按钮被点击的次数来推测有多少用户对此感兴趣。那么我们可以使用以下的代码来实现这个功能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>...</span></span>
<span class="line"><span>params = {</span></span>
<span class="line"><span>    eventCategory:</span></span>
<span class="line"><span>    &#39;Button&#39;</span></span>
<span class="line"><span>    ,</span></span>
<span class="line"><span>    eventAction:</span></span>
<span class="line"><span>    &#39;Click&#39;</span></span>
<span class="line"><span>    ,</span></span>
<span class="line"><span>    eventLabel:</span></span>
<span class="line"><span>    &#39;Show interest&#39;</span></span>
<span class="line"><span>    ,</span></span>
<span class="line"><span>    eventValue:</span></span>
<span class="line"><span>    1</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>showInterest() {</span></span>
<span class="line"><span>    ga(&#39;send&#39;, &#39;event&#39;, this.params);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>现在看下这段代码实际上做了什么。正如前面说到，当我们向 Google Analytics 发送数据的时候，Google Analytics 就会记录下来。因此我们可以向 <code>send()</code> 方法传递不同的参数，以区分不同的事件，例如两个不同按钮的点击记录。</p><p>1、首先我们定义了一个 <code>params</code> 对象，这个对象包含了以下几个字段：</p><ol><li><code>eventCategory</code> – 交互发生的对象，这里对应的是按钮（button）</li><li><code>eventAction</code> – 发生的交互的类型，这里对应的是点击（click）</li><li><code>eventLabel</code> – 交互动作的标识，这里对应的是这个按钮的内容，也就是“感兴趣”</li><li><code>eventValue</code> – 与每个发生的事件实例相关联的值</li></ol><p>由于这个例子中是要统计点击了“感兴趣”按钮的用户数，因此我们把 <code>eventValue</code> 的值定为 1。</p><p>2、对象构造完成之后，下一步就是将 <code>params</code> 对象作为请求负载发送到 Google Analytics，而这一步是通过事件绑定将 <code>showInterest()</code> 绑定在按钮上实现的。这也是使用 Google Analytics 追踪中最常用的发送事件方法。</p><p>至此，Google Analytics 就可以通过记录按钮的点击次数来统计感兴趣的用户数了。</p><h4 id="追踪社交活动" tabindex="-1">追踪社交活动 <a class="header-anchor" href="#追踪社交活动" aria-label="Permalink to “追踪社交活动”">​</a></h4><p>Google Analytics 还可以通过应用程序追踪用户在社交媒体上的互动。其中一种场景就是在应用中放置类似 Facebook 的点赞按钮，下面我们来看看如何使用 Google Analytics 来追踪这一行为。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>...</span></span>
<span class="line"><span>fbLikeParams = {</span></span>
<span class="line"><span>    socialNetwork:</span></span>
<span class="line"><span>        &#39;Facebook&#39;,</span></span>
<span class="line"><span>    socialAction:</span></span>
<span class="line"><span>        &#39;Like&#39;,</span></span>
<span class="line"><span>    socialTarget:</span></span>
<span class="line"><span>        &#39;https://facebook.com/mypage&#39;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>fbLike() {</span></span>
<span class="line"><span>    ga(&#39;send&#39;, &#39;social&#39;, this.fbLikeParams);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果你觉得这段代码似曾相识，那是因为它确实跟上面统计“感兴趣”按钮点击次数的代码非常相似。下面我们继续看其中每一步的内容：</p><p>1、构造发送的数据负载，其中包括以下字段：</p><ol><li><code>socialNetwork</code> – 交互发生的社交媒体，例如 Facebook、Twitter 等等</li><li><code>socialAction</code> – 发生的交互类型，例如点赞、发表推文、分享等等</li><li><code>socialTarget</code> – 交互的目标 URL，一般是社交媒体账号的主页</li></ol><p>2、下一步是增加一个函数来发送整个交互记录。和统计按钮点击数量时相比，这里使用 <code>send()</code> 的方式有所不同。另外，我们还需要把这个函数绑定到已有的点赞按钮上。</p><p>在追踪用户交互方面，Google Analytics 还可以做更多的事情，其中最重要的一种是针对异常的追踪，这让我们可以通过 Google Analytics 来追踪应用程序中出现的错误和异常。在本文中我们就不赘述这一点了，但我们鼓励读者自行探索。</p><h3 id="用户识别" tabindex="-1">用户识别 <a class="header-anchor" href="#用户识别" aria-label="Permalink to “用户识别”">​</a></h3><h4 id="隐私是一项权利-而不是奢侈品" tabindex="-1">隐私是一项权利，而不是奢侈品 <a class="header-anchor" href="#隐私是一项权利-而不是奢侈品" aria-label="Permalink to “隐私是一项权利，而不是奢侈品”">​</a></h4><p>Google Analytics 除了可以记录很多用户的操作和交互活动之外，这一节还将介绍一个不太常见的功能，就是可以控制是否对用户的身份进行追踪。</p><h4 id="cookies" tabindex="-1">Cookies <a class="header-anchor" href="#cookies" aria-label="Permalink to “Cookies”">​</a></h4><p>Google Analytics 追踪用户活动的方式是基于 Cookies 的，因此我们可以自定义 Cookies 的名称以及一些其它的内容，请看下面这段代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trackingID =</span></span>
<span class="line"><span>    &#39;UA-139883813-1&#39;</span></span>
<span class="line"><span>;</span></span>
<span class="line"><span>cookieParams = {</span></span>
<span class="line"><span>    cookieName: &#39;myGACookie&#39;,</span></span>
<span class="line"><span>    cookieDomain: window.location.hostname,</span></span>
<span class="line"><span>    cookieExpires: 604800</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>ngOnInit() {</span></span>
<span class="line"><span>    ga(&#39;create&#39;, this.trackingID, this.cookieParams);</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在上面这段代码中，我们设置了 Google Analytics Cookies 的名称、域以及过期时间，这就让我们能够将不同网站或 Web 应用的 Cookies 区分开来。因此我们需要为我们自己的应用程序的 Google Analytics 追踪器的 Cookies 设置一个自定义的标识1，而不是一个自动生成的随机标识。</p><h4 id="ip-匿名" tabindex="-1">IP 匿名 <a class="header-anchor" href="#ip-匿名" aria-label="Permalink to “IP 匿名”">​</a></h4><p>在某些场景下，我们可能不需要知道应用程序的流量来自哪里。例如对于一个按钮点击的追踪器，我们只需要关心按钮的点击量，而不需要关心点击者的地理位置。在这种场景下，Google Analytics 允许我们只追踪用户的操作行为，而不获取到用户的 IP 地址。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ipParams = {</span></span>
<span class="line"><span>    anonymizeIp: true</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>ngOnInit() {</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    ga(&#39;set&#39;, this.ipParams);</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在上面这段代码中，我们将 Google Analytics 追踪器的 <code>abibymizeIp</code> 参数设置为 <code>true</code>。这样用户的 IP 地址就不会被 Google Analytics 所追踪，这可以让用户知道自己的隐私正在被保护。</p><h4 id="不被跟踪" tabindex="-1">不被跟踪 <a class="header-anchor" href="#不被跟踪" aria-label="Permalink to “不被跟踪”">​</a></h4><p>还有些时候用户可能不希望自己的行为受到追踪，而 Google Analytics 也允许这样的需求。因此也存在让用户不被追踪的选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>...</span></span>
<span class="line"><span>optOut() {</span></span>
<span class="line"><span>    window[&#39;ga-disable-UA-139883813-1&#39;] = true;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>...</span></span></code></pre></div><p><code>optOut()</code> 是一个自定义函数，它可以禁用页面中的 Google Analytics 追踪，我们可以使用按钮或复选框上得事件绑定来使用这一个功能，这样用户就可以选择是否会被 Google Analytics 追踪。</p><p>在本文中，我们讨论了 Google Analytics 集成到单页应用时的难点，并探索出了一种相关的解决方法。我们还了解到了如何在单页应用中追踪页面访问和用户交互，例如按钮点击、社交媒体活动等。</p><p>最后，我们还了解到 Google Analytics 为用户提供了保护隐私的功能，尤其是用户的一些隐私数据并不需要参与到统计当中的时候。而用户也可以选择完全不受到 Google Analytics 的追踪。除此以外，Google Analytics 还可以做到很多其它的事情，这就需要我们继续不断探索了。</p><hr>`,57)),e("p",null,[a[7]||(a[7]=s("via: ",-1)),l(n,{href:"https://opensourceforu.com/2019/10/all-that-you-can-do-with-google-analytics-and-more/"},{default:i(()=>[...a[6]||(a[6]=[s("https://opensourceforu.com/2019/10/all-that-you-can-do-with-google-analytics-and-more/",-1)])]),_:1})]),e("p",null,[a[12]||(a[12]=s("作者：",-1)),l(n,{href:"https://opensourceforu.com/author/ashwin-sathian/"},{default:i(()=>[...a[8]||(a[8]=[s("Ashwin Sathian",-1)])]),_:1}),a[13]||(a[13]=s(" 选题：",-1)),l(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...a[9]||(a[9]=[s("lujun9972",-1)])]),_:1}),a[14]||(a[14]=s(" 译者：",-1)),l(n,{href:"https://github.com/HankChow"},{default:i(()=>[...a[10]||(a[10]=[s("HankChow",-1)])]),_:1}),a[15]||(a[15]=s(" 校对：",-1)),l(n,{href:"https://github.com/wxy"},{default:i(()=>[...a[11]||(a[11]=[s("wxy",-1)])]),_:1})]),e("p",null,[a[18]||(a[18]=s("本文由 ",-1)),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[16]||(a[16]=[s("LCTT",-1)])]),_:1}),a[19]||(a[19]=s(" 原创编译，",-1)),l(n,{href:"https://linux.cn/"},{default:i(()=>[...a[17]||(a[17]=[s("Linux中国",-1)])]),_:1}),a[20]||(a[20]=s(" 荣誉推出",-1))])])}const C=t(d,[["render",g]]);export{A as __pageData,C as default};
